quoted_support:
if [ "$STATE" != "ONLINE" ]; then ISSUES+=("CRITICAL: Pool $pool is in state $STATE"); fi
if [ "$CAP" -gt 85 ]; then ISSUES+=("WARNING: Pool $pool is ${CAP}% full (above 85% threshold)"); fi
if [ "$FRAG" -gt 50 ]; then ISSUES+=("WARNING: Pool $pool fragmentation is ${FRAG}% (above 50%)")
